from django.db import migrations, models

CODIGO_PANEL = "PANEL"
ROL_JUNIOR = "Contador Junior"


def crear_seccion_panel(apps, schema_editor):
    """
    Agrega «Panel principal» a la matriz de módulos por rol en las
    instalaciones que ya tienen datos. Queda habilitado para todos menos para
    el Contador Junior (decisión del usuario, 7-oct-2026); el Administrador lo
    cambia desde Equipo y roles. En una base vacía no hace nada: los datos los
    crea `cargar_datos_iniciales`.
    """
    Modulo = apps.get_model("seguridad", "Modulo")
    Rol = apps.get_model("seguridad", "Rol")
    PermisoRolModulo = apps.get_model("seguridad", "PermisoRolModulo")
    if not Modulo.objects.exists():
        return
    panel, _ = Modulo.objects.get_or_create(
        codigo_modulo=CODIGO_PANEL, defaults={"nombre_modulo": "Panel principal"}
    )
    for rol in Rol.objects.all():
        PermisoRolModulo.objects.get_or_create(
            rol=rol, modulo=panel, defaults={"habilitado": rol.nombre_rol != ROL_JUNIOR}
        )


def quitar_seccion_panel(apps, schema_editor):
    apps.get_model("seguridad", "Modulo").objects.filter(codigo_modulo=CODIGO_PANEL).delete()


